// Manual reproduction of the issue & fix verification
import { AsyncQueue } from "../src/queue.ts";

async function main() {
  console.log("--- Case 1: failing handler should report failure ---");
  {
    const q = new AsyncQueue<string>({ retryDelay: 0 });
    q.enqueue("fail", { maxAttempts: 3 });
    const dequeued = q.dequeue();
    const handler = () => { throw new Error("boom"); };
    const r1 = await q.processJob(dequeued, handler);
    console.log("r1.success =", r1.success, "(expected false)");
    console.log("r1.job.attempts =", r1.job.attempts, "(expected 1)");
    console.log("queue size =", q.size(), "(expected 1: re-enqueued)");
  }

  console.log("\n--- Case 2: max attempts reached -> not re-enqueued ---");
  {
    const q = new AsyncQueue<string>({ retryDelay: 0 });
    q.enqueue("fail", { maxAttempts: 1 });
    const dequeued = q.dequeue();
    const handler = () => { throw new Error("boom"); };
    const r = await q.processJob(dequeued, handler);
    console.log("r.success =", r.success, "(expected false)");
    console.log("r.job.attempts =", r.job.attempts, "(expected 1)");
    console.log("queue size =", q.size(), "(expected 0: maxAttempts reached)");
  }

  console.log("\n--- Case 3: success path still works ---");
  {
    const q = new AsyncQueue<string>();
    q.enqueue("ok");
    const dequeued = q.dequeue();
    const r = await q.processJob(dequeued, async () => {});
    console.log("r.success =", r.success, "(expected true)");
    console.log("r.job.attempts =", r.job.attempts, "(expected 1)");
    console.log("queue size =", q.size(), "(expected 0)");
  }

  console.log("\n--- Case 4: processNext surfaces errors via retry ---");
  {
    const q = new AsyncQueue<string>();
    q.enqueue("x", { maxAttempts: 2 });
    let called = 0;
    const handler = () => { called++; throw new Error("oops"); };
    const r1 = await q.processNext(handler);
    console.log("r1.success =", r1.success, "(expected false), called =", called, "(expected 1)");
    const r2 = await q.processNext(handler);
    console.log("r2.success =", r2.success, "(expected false), called =", called, "(expected 2)");
    console.log("queue empty =", q.isEmpty(), "(expected true)");
    const r3 = await q.processNext(handler);
    console.log("r3 =", r3, "(expected null)");
  }
}

main().catch((e) => { console.error("ERR", e); process.exit(1); });

