    q.enqueue("fail", { maxAttempts: 1 });
    const dequeued = q.dequeue();
    const handler = () => { throw new Error("boom"); };
    const r = await q.processJob(dequeued, handler);
    console.log("r.success =", r.success, "(expected false)");
    console.log("r.job.attempts =", r.job.attempts, "(expected 1)");
    console.log("queue size =", q.size(), "(expected 0: maxAttempts reached)");
  }

  console.log("\n--- Case 3: success path still works ---");
  {
    const q = new AsyncQueue<string>();
    q.enqueue("ok");
    const dequeued = q.dequeue();
    const r = await q.processJob(dequeued, async () => {});
    console.log("r.success =", r.success, "(expected true)");
    console.log("r.job.attempts =", r.job.attempts, "(expected 1)");
    console.log("queue size =", q.size(), "(expected 0)");
  }

  console.log("\n--- Case 4: processNext surfaces errors via retry ---");
  {
    const q = new AsyncQueue<string>();
    q.enqueue("x", { maxAttempts: 2 });
